import random

# already covered as the probability distribution in this topic
distribution = {"cat": 0.5, "dog": 0.3, "fox": 0.15, "yak": 0.05}

def greedy_decode(distribution):
    # already covered as greedy decoding in this topic
    return max(distribution, key=distribution.get)

def random_sample(distribution):
    # already covered as random sampling from the distribution in this topic
    words = list(distribution.keys())
    weights = list(distribution.values())
    return random.choices(words, weights=weights, k=1)[0]

random.seed(0)
print("Greedy decoding (already covered in this topic), run 5 times:")
for _ in range(5):
    print(" ", greedy_decode(distribution))

print("\nRandom sampling (already covered in this topic), run 5 times:")
for _ in range(5):
    print(" ", random_sample(distribution))
